"""Holm correction across the article's headline tests."""
import json; from statsmodels.stats.multitest import multipletests
R=json.load(open('data_out/results_round.json')); T=json.load(open('data_out/results_tactics.json')); B=json.load(open('data_out/results_breaks.json')); C=json.load(open('data_out/results_career.json'))
H={'next round: stopped (raw chi-square)':R['raw_tests']['stopped_next']['p'],'next round: knocked down again (raw)':R['raw_tests']['kd_next']['p'],'next round: stopped (adjusted)':R['adjusted']['stopped_next']['kd_r']['p'],'next round: knocked down again (adjusted)':R['adjusted']['kd_next']['kd_r']['p'],
 'survivors: age trend in stoppage':T['age_trend_stopped'][1],'survivors: knockdown-history trend':T['history_trend_stopped'][1],'behaviour: takedown attempts':T['before_after_td_att_per_round']['wilcoxon_p'],'behaviour: strikes thrown':T['before_after_sig_att_per_round']['wilcoxon_p'],'behaviour: distance share':T['before_after_distance_share']['wilcoxon_p'],
 'wrestling habit x knockdown':T['habit_logit_stopped_next']['kd_r:wr']['p'],'grappling round: head strikes (exploratory)':T['B_tests']['head_mw_p'],'break: quick v long (Fisher)':B['tests_all']['ko_loss_quick_v_long']['fisher_p'],'break: long break (adjusted)':B['tests_all']['ko_loss_adj']['long_break']['p'],'break after KO with knockdown: quick v long':B['tests_ko_with_knockdown']['ko_loss_quick_v_long']['fisher_p'],
 'career: volume v winning, age removed':C['volume']['win']['partial_age'][1],'matched dose: later KO loss':C['matched_dose']['outcomes']['l_ko']['wilcoxon_p'],'matched early knockdown: later KO loss':C['matched_early_kd']['outcomes']['l_ko']['wilcoxon_p'],'matched early knockdown: later knockdowns':C['matched_early_kd']['outcomes']['l_kdany']['wilcoxon_p'],
 'career: prior knockdowns -> knockdown':C['joint']['kd_any']['cum_kd']['p'],'career: prior KO losses -> KO loss':C['joint']['ko_loss']['cum_ko_loss']['p'],'first loss: KO v submission (all)':C['logrank KO/TKO v Submission']['p'],'first loss: KO v submission (after a win)':C['first_loss_after_a_win']['ko_v_sub_p']}
adj=multipletests(list(H.values()),method='holm')[1]; out={k:dict(p=float(p),holm=float(a)) for (k,p),a in zip(H.items(),adj)}; json.dump(out,open('data_out/results_holm.json','w'),indent=1)
for k,v in out.items(): print(f"{k:55s} p={v['p']:.4g}  holm={v['holm']:.4g}")
